V3_JS = r'''
function societyPanel(){const m=current().step.society_metrics_v3,cohesion=m.viewpoint_cohesion,prevalence=m.structural_prevalence;$('society').innerHTML=`<h2>Xã hội động</h2><div class="pill">${esc(current().run.timestamp)} / k${current().step.deliberation_step}</div><div class="profile-summary"><b>Quan điểm trội:</b> ${esc(m.dominant_viewpoint||'không')}<br><b>Chỉ báo hội tụ:</b> ${m.convergence_proxy.toFixed(3)} · <b>Chỉ báo đồng thuận:</b> ${m.consensus_proxy.toFixed(3)}<br><b>Phân mảnh:</b> ${m.fragmentation_proxy.toFixed(3)} · <b>Phân cực:</b> ${m.polarization_proxy.toFixed(3)}</div><div class="proxy-note">Đây là chỉ báo cấu trúc của mô phỏng, không phải mức ủng hộ hay đồng thuận xã hội thật.</div><h3>GẮN KẾT / ĐỘ PHỔ BIẾN</h3>${Object.keys(cohesion).map(id=>`<div class="society-row"><span><b>${esc(id)}</b><br><small>gắn kết ${cohesion[id].cohesion.toFixed(3)} · tách ${cohesion[id].split_score.toFixed(3)}</small></span><b>${(prevalence[id]?.structural_prevalence||0).toFixed(3)}</b></div>`).join('')}<h3>ỨNG VIÊN TÁCH</h3>${m.split_candidates.map(x=>`<div class="card">${esc(x.agent_id)} · ${x.score.toFixed(3)} / ${x.threshold}</div>`).join('')||'<div class="card">Không có.</div>'}<h3>ỨNG VIÊN GỘP</h3>${m.merge_candidates.map(x=>`<div class="card">${x.agents.map(esc).join(' + ')} · ${x.score.toFixed(3)} / ${x.threshold}</div>`).join('')||'<div class="card">Không có.</div>'}<h3>THÀNH PHẦN LIÊN THÔNG</h3><div class="card">${m.weakly_connected_components.map(x=>x.map(esc).join(' ↔ ')).join('<br>')}<br><small>Tách biệt: ${m.isolated_agents.map(esc).join(', ')||'không'}</small></div>`}
function highlightAgents(ids){document.querySelectorAll('.agent').forEach(n=>n.classList.toggle('event-highlight',ids.includes(n.dataset.id)))}
function eventsPanel(){const ti=state.t,ki=state.k,visible=TRACE.society_events.filter(e=>{const ei=TRACE.timestamps.findIndex(r=>r.timestamp===e.timestamp);return ei<ti||(ei===ti&&e.deliberation_step<=ki)});$('events').innerHTML=`<h2>Sự kiện xã hội</h2><div class="proxy-note">Sự kiện xã hội là sự kiện cấu trúc có nguồn gốc truy vết, không phải trục thời gian thứ ba.</div>${visible.map(e=>`<div class="event-card" data-event-agents="${esc(e.involved_agents.join(','))}"><small>${esc(e.timestamp)} / k${e.deliberation_step}</small><br><b>${esc(e.event_type)}</b><br>${esc(e.involved_agents.join(' ↔ ')||'toàn xã hội')}<br><small>${esc(e.explanation)}</small></div>`).join('')||'<div class="empty">Chưa có sự kiện xã hội tới bước này.</div>'}`;document.querySelectorAll('[data-event-agents]').forEach(card=>card.onclick=()=>highlightAgents(card.dataset.eventAgents.split(',').filter(Boolean)))}
function enhanceReasoningPanel(){if(state.edge!==null)return;const id=state.agent;if(!id)return;const step=current().step,owned=Object.keys(step.agent_states_after[id]?.belief_states||{}),rows=owned.map(arg=>step.argumentation_semantics.results[arg]).filter(Boolean);if(!rows.length)return;const box=document.createElement('section');box.className='semantics-compare';box.innerHTML=`<h3>ĐIỂM KINH NGHIỆM ↔ NGỮ NGHĨA LẬP LUẬN</h3>${rows.map(x=>`<div class="semantic-row"><span><b>${esc(x.argument_id)}</b><br>${esc(x.semantic_status)}</span><span>H ${x.heuristic_score.toFixed(3)} · S <b>${x.semantic_score.toFixed(3)}</b> · điều chỉnh <b>${x.revision_blend_score.toFixed(3)}</b></span></div>`).join('')}<small>${esc(step.argumentation_semantics.method)} · chỉ báo khả năng chấp nhận, không phải sự thật thực tế.</small>`;$('reasoning').appendChild(box)}
function decorateV3Graph(){const step=current().step,m=step.society_metrics_v3,split=new Set(m.split_candidates.map(x=>x.agent_id)),conflict=new Set(step.society_events.filter(e=>e.event_type==='PERSISTENT_CONFLICT').flatMap(e=>e.involved_agents));document.querySelectorAll('.agent').forEach(node=>{const id=node.dataset.id,p=m.structural_prevalence[id]?.structural_prevalence||0,c=m.viewpoint_cohesion[id]?.cohesion||0;node.classList.toggle('dominant',id===m.dominant_viewpoint);node.classList.toggle('persistent-conflict',conflict.has(id));const rect=node.querySelector('rect');rect.style.strokeWidth=(2.5+p*2).toFixed(2);if(c>.72)rect.style.filter=`drop-shadow(0 0 ${Math.round(3+c*5)}px rgba(22,185,120,.42))`;if(id===m.dominant_viewpoint||split.has(id)){const badge=document.createElementNS('http://www.w3.org/2000/svg','text');badge.setAttribute('x','82');badge.setAttribute('y','-8');badge.setAttribute('class',`v3-badge ${split.has(id)?'v3-split':''}`);badge.textContent=id===m.dominant_viewpoint?'◆ TRỘI':'◇ TÁCH?';node.appendChild(badge)}})}

let workspaceMode='agent',managerArgument=params.get('risk_arg'),riskStart=0,riskEnd=state.t,riskPreset='current';
function riskWindowId(){const options=TRACE.risk_monitoring.snapshot_options;return`${options[riskStart].snapshot_id}__${options[riskEnd].snapshot_id}`}
function riskWindow(){return TRACE.risk_monitoring.by_window[riskWindowId()]}
function riskRow(argumentId){return riskWindow().ranked_arguments.find(row=>row.argument_id===argumentId)}
const RISK_BAND_LABEL={LOW:'THẤP',MEDIUM:'TRUNG BÌNH',MEDIUM_HIGH:'TRUNG BÌNH–CAO',HIGH:'CAO'};
const EVIDENCE_LABEL={NONE:'KHÔNG CÓ',WEAK:'YẾU',LOW:'THẤP',MEDIUM:'TRUNG BÌNH',MEDIUM_HIGH:'TRUNG BÌNH–CAO',HIGH:'CAO',STRONG:'MẠNH'};
const ALERT_LABEL={HIGH_RISK:'RỦI RO CAO',RISK_INCREASE:'RỦI RO TĂNG',CONFLICT_INCREASE:'XUNG ĐỘT TĂNG',STEERING_PERSISTS:'ĐỊNH HƯỚNG KÉO DÀI'};
function riskBandLabel(value){return RISK_BAND_LABEL[value]||value}
function evidenceLabel(value){return EVIDENCE_LABEL[value]||value}
function alertLabel(value){return ALERT_LABEL[value]||value}
function scoreCard(label,value){return`<div class="risk-score-card"><small>${esc(label)}</small><b>${typeof value==='number'?value.toFixed(4):esc(value)}</b></div>`}
function riskConfig(){return TRACE.risk_monitoring.methodology.config.risk}
function thresholdCard(label,value,threshold,highLabel,normalLabel){const high=value>=threshold,symbol=high?'≥':'<';return`<div class="risk-score-card"><small>${esc(label)}</small><b>${value.toFixed(4)}</b><span class="threshold-compare ${high?'high':'normal'}">${value.toFixed(3)} ${symbol} ${threshold.toFixed(2)} → ${esc(high?highLabel:normalLabel)}</span></div>`}
function snapshotDate(option){const compact=value=>{const [year,month,day]=value.split('-');return`${day}/${month}/${year}`};return option.date_start===option.date_end?compact(option.date_start):`${compact(option.date_start)}–${compact(option.date_end)}`}
function snapshotOption(option,index,limit,kind){const disabled=kind==='start'?index>limit:index<limit;return`<option value="${index}" ${disabled?'disabled':''}>${esc(option.snapshot_id)} · ${snapshotDate(option)}</option>`}
function setRiskWindow(start,end,preset='custom'){const last=TRACE.risk_monitoring.snapshot_options.length-1;riskStart=Math.max(0,Math.min(last,start));riskEnd=Math.max(0,Math.min(last,end));if(riskStart>riskEnd){if(preset==='from')riskEnd=riskStart;else riskStart=riskEnd}riskPreset=preset==='from'||preset==='to'?'custom':preset;state.t=riskEnd;state.k=0;managerArgument=null;renderRiskMonitoring()}
function setWorkspace(mode){workspaceMode=mode;stopPlayback();document.body.classList.toggle('risk-mode',mode==='risk');$('riskWorkspace').hidden=mode!=='risk';document.querySelectorAll('[data-workspace]').forEach(button=>button.classList.toggle('active',button.dataset.workspace===mode));if(mode==='risk'){if(riskPreset==='current'){riskStart=0;riskEnd=state.t}renderRiskMonitoring()}else render()}
function renderRiskHeader(window){const options=TRACE.risk_monitoring.snapshot_options,last=options.length-1;$('riskHeader').innerHTML=`<div class="risk-header-main"><h1>Giám sát rủi ro</h1><p>CTQ · H=[${esc(window.start_snapshot)} → ${esc(window.end_snapshot)}]</p><small>${esc(window.H_l)} → ${esc(window.H_u)} · chỉ xếp hạng A_D</small><small class="snapshot-note">Cửa sổ H được xác định theo các mốc quan sát t1–t6; dữ liệu hiện tại không được mô hình hóa liên tục theo từng ngày.</small></div><div class="risk-window-controls"><div class="risk-window-selectors"><label>Từ <select id="riskFrom">${options.map((option,index)=>snapshotOption(option,index,riskEnd,'start')).join('')}</select></label><label>Đến <select id="riskTo">${options.map((option,index)=>snapshotOption(option,index,riskStart,'end')).join('')}</select></label></div><div class="risk-presets"><button data-risk-preset="current" class="${riskPreset==='current'?'active':''}">Từ đầu đến hiện tại</button><button data-risk-preset="full" class="${riskPreset==='full'?'active':''}">Toàn kỳ</button><button data-risk-preset="recent2" class="${riskPreset==='recent2'?'active':''}">2 mốc gần</button><button data-risk-preset="recent3" class="${riskPreset==='recent3'?'active':''}">3 mốc gần</button><button data-risk-preset="custom" class="${riskPreset==='custom'?'active':''}">Tùy chọn</button></div></div>`;$('riskFrom').value=String(riskStart);$('riskTo').value=String(riskEnd);$('riskFrom').onchange=event=>setRiskWindow(+event.target.value,riskEnd,'from');$('riskTo').onchange=event=>setRiskWindow(riskStart,+event.target.value,'to');document.querySelectorAll('[data-risk-preset]').forEach(button=>button.onclick=()=>{const preset=button.dataset.riskPreset;if(preset==='current')setRiskWindow(0,riskEnd,'current');else if(preset==='full')setRiskWindow(0,last,'full');else if(preset==='recent2')setRiskWindow(Math.max(0,riskEnd-1),riskEnd,'recent2');else if(preset==='recent3')setRiskWindow(Math.max(0,riskEnd-2),riskEnd,'recent3');else{riskPreset='custom';renderRiskHeader(riskWindow())}})}
function renderRiskSummary(window){const cfg=riskConfig();$('riskSummary').innerHTML=`<div class="risk-stat"><small>Cửa sổ quan sát H</small><b>${esc(window.start_snapshot)} → ${esc(window.end_snapshot)}</b><small class="threshold-line">${esc(window.H_l)} → ${esc(window.H_u)}</small></div><div class="risk-stat"><small>A_D đang giám sát</small><b>${window.monitored_argument_count}</b><small class="threshold-line">Trong lát cắt snapshot đã chọn</small></div><div class="risk-stat"><small class="risk-stat-label">Rủi ro cao <i tabindex="0" class="metric-info" data-tip="RS(x,H) = αC + βS + γCS&#10;Rủi ro cao khi RS(x,H) ≥ τ_R">i</i></small><b>${window.high_risk_count}</b><small class="threshold-line">Ngưỡng: RS ≥ ${cfg.risk_alert_threshold.toFixed(2)}</small></div><div class="risk-stat"><small class="risk-stat-label">Xung đột cao <i tabindex="0" class="metric-info" data-tip="C(x,H) = max_{k ∈ A_K(H)} c(x,k,H)&#10;Xung đột cao khi C(x,H) ≥ τ_C">i</i></small><b>${window.high_conflict_count}</b><small class="threshold-line">Ngưỡng: C ≥ ${cfg.high_conflict_threshold.toFixed(2)}</small></div><div class="risk-stat"><small class="risk-stat-label">Định hướng cao <i tabindex="0" class="metric-info" data-tip="S(x,H) = Σ I(x,x_j) / max(1, |A_D(H)|−1)&#10;Định hướng cao khi S(x,H) ≥ τ_S">i</i></small><b>${window.high_steering_count}</b><small class="threshold-line">Ngưỡng: S ≥ ${cfg.high_steering_threshold.toFixed(2)}</small></div>`}
function renderRiskTable(window){if(!managerArgument||!riskRow(managerArgument))managerArgument=window.ranked_arguments[0]?.argument_id||null;$('riskTableBody').innerHTML=window.ranked_arguments.map(row=>{const trend=row.trend.risk_delta>0?'▲ '+row.trend.risk_delta.toFixed(3):row.trend.risk_delta<0?'▼ '+Math.abs(row.trend.risk_delta).toFixed(3):'—';return`<tr class="${row.argument_id===managerArgument?'selected':''}" data-risk-argument="${esc(row.argument_id)}"><td class="risk-priority"><b>#${row.priority_rank}</b></td><td class="risk-argument-id"><b>${esc(row.argument_id)}</b><br><small>${esc(row.owner_viewpoint)}</small></td><td class="risk-conclusion">${esc(row.conclusion)}</td><td class="score">${row.conflict_score.toFixed(3)}</td><td class="score">${row.steering_score.toFixed(3)}</td><td class="score">${row.risk_score.toFixed(3)}</td><td><span class="risk-band ${row.risk_band}">${esc(riskBandLabel(row.risk_band))}</span></td><td class="risk-quality">${esc(evidenceLabel(row.assessment_quality.category))}</td><td class="risk-trend-cell">${trend}</td><td><button class="inspect-button" data-inspect="${esc(row.argument_id)}">Đồ thị ↗</button></td></tr>`}).join('');document.querySelectorAll('[data-risk-argument]').forEach(tr=>tr.onclick=()=>{managerArgument=tr.dataset.riskArgument;renderRiskTable(window);renderRiskDetail()});document.querySelectorAll('[data-inspect]').forEach(button=>button.onclick=event=>{event.stopPropagation();inspectInSociety(button.dataset.inspect)})}
function renderRiskDetail(){const row=riskRow(managerArgument),panel=$('riskDetail'),window=riskWindow();if(!row){panel.innerHTML='<div class="empty">Chưa có A_D trong H.</div>';return}const pair=row.conflict_evidence.maximizing_pair,top=row.steering_evidence.pairwise_influence.filter(item=>item.I>0).slice(0,5),history=TRACE.risk_monitoring.argument_history[row.argument_id],coeff=row.risk_detail.coefficients,cfg=riskConfig();panel.innerHTML=`<h2>${esc(row.argument_id)}</h2><div class="pill">Ưu tiên #${row.priority_rank}</div><span class="risk-band ${row.risk_band}">${esc(riskBandLabel(row.risk_band))}</span><p>${esc(row.conclusion)}</p><button class="inspect-button" id="inspectSelected">Xem trong xã hội tác tử</button><div class="risk-score-grid">${thresholdCard('Xung đột C',row.conflict_score,cfg.high_conflict_threshold,'XUNG ĐỘT CAO','chưa cao')}${thresholdCard('Định hướng S',row.steering_score,cfg.high_steering_threshold,'ĐỊNH HƯỚNG CAO','chưa cao')}${thresholdCard('Rủi ro RS',row.risk_score,cfg.risk_alert_threshold,'RỦI RO CAO','chưa cao')}${scoreCard('Chất lượng đánh giá',evidenceLabel(row.assessment_quality.category))}</div><h3>XUNG ĐỘT · C(x,H)=max c(x,k,H)</h3>${pair?`<div class="evidence-line"><b>${esc(row.argument_id)}</b> → TẤN CÔNG → <b>${esc(pair.reference_argument_id)}</b><br>c=${pair.score.toFixed(4)} · tấn công ${pair.attack} · độ tin cậy ${pair.relation_confidence} · hiệu lực ${pair.validity} · thẩm quyền ${pair.authority}<br>Quan hệ: ${pair.relation_ids.map(esc).join(', ')}<br>Nguồn: ${pair.source_ids.map(esc).join(', ')}</div>`:'<div class="evidence-line">Không có quan hệ tấn công chính tắc A_D → A_K đủ điều kiện trong H; C=0. Không suy diễn mâu thuẫn chỉ từ văn bản.</div>'}<h3>ĐỊNH HƯỚNG · S=Σ I(x,xⱼ) đã chuẩn hóa</h3><div class="manager-note">${esc(row.steering_evidence.explanation)}</div>${top.map(item=>`<div class="evidence-line"><b>→ ${esc(item.target_argument_id)}</b> · ${esc(evidenceLabel(item.evidence_level))}<br>I=${item.T.toFixed(1)} × ${item.L.toFixed(4)} × ${item.P.toFixed(4)} = <b>${item.I.toFixed(4)}</b><br>Quan hệ: ${item.relation_ids.map(esc).join(', ')||'—'} · Tương tác: ${item.interaction_ids.map(esc).join(', ')||'—'} · Điều chỉnh niềm tin: ${item.revision_ids.map(esc).join(', ')||'—'}</div>`).join('')||'<div class="evidence-line">Không có giá trị ảnh hưởng theo cặp I dương.</div>'}<div class="evidence-line">${row.steering_evidence.downstream_argument_count} lập luận phía sau · ${row.steering_evidence.affected_viewpoint_count} quan điểm · ${row.steering_evidence.interaction_count} tương tác · ${row.steering_evidence.belief_revision_count} lần điều chỉnh · độ sâu ${row.steering_evidence.temporal_depth} · độ bền ${row.steering_evidence.persistence.toFixed(3)}</div><h3>RỦI RO · ĐƯỜNG CƠ SỞ THEO CẤU HÌNH</h3><div class="formula-box">RS = ${coeff.alpha}C + ${coeff.beta}S + ${coeff.gamma}CS<br>${row.risk_detail.contributions.conflict.toFixed(4)} + ${row.risk_detail.contributions.steering.toFixed(4)} + ${row.risk_detail.contributions.interaction_cs.toFixed(4)} = ${row.risk_score.toFixed(4)}</div><p class="manager-note">Đây là cách vận hành cơ sở của f(C,S); các hệ số có thể cấu hình và chưa được hiệu chỉnh thực nghiệm. Rủi ro dùng để ưu tiên rà soát, không khẳng định mức độ gây hại thực tế.</p><h3>DIỄN BIẾN CỘNG DỒN · Hₜ</h3><p class="manager-note">Chuỗi dưới đây luôn là t1→t1, t1→t2, …, t1→t6; cửa sổ đang chọn ${esc(window.start_snapshot)}→${esc(window.end_snapshot)} là một lát cắt phân tích riêng.</p><div class="risk-trend">${TRACE.timestamps.map(run=>{const point=history.find(item=>item.end_snapshot===run.timestamp);return`<div class="trend-point">${esc(run.timestamp)}${point?`<b>RS ${point.risk.toFixed(3)}</b>C ${point.conflict.toFixed(2)} · S ${point.steering.toFixed(2)}`:'<b>CHƯA CÓ</b>chưa xuất hiện'}</div>`}).join('')}</div><h3>CẢNH BÁO</h3>${row.alerts.map(alert=>`<div class="alert-line"><b>${esc(alertLabel(alert.type))}</b><br>${esc(alert.reason)}</div>`).join('')||(window.is_cumulative?'<div class="evidence-line">Không có cảnh báo mới trong H này.</div>':'<div class="evidence-line">Lát cắt tùy chọn không được diễn giải như một bước trong chuỗi cảnh báo cộng dồn.</div>')}<h3>GIẢI THÍCH TẤT ĐỊNH</h3><div class="evidence-line">${esc(row.conflict_evidence.explanation)}<br><br>${esc(row.risk_detail.explanation)}<br><br>${esc(row.priority_explanation)}</div>`;$('inspectSelected').onclick=()=>inspectInSociety(row.argument_id)}
function renderRiskMonitoring(){const window=riskWindow();renderRiskHeader(window);renderRiskSummary(window);renderRiskTable(window);renderRiskDetail()}
function inspectInSociety(argumentId){const row=riskRow(argumentId);state.t=riskEnd;state.agent=row.owner_viewpoint;state.edge=null;setWorkspace('agent');activateReasoningTab();render();setTimeout(()=>{const detail=[...document.querySelectorAll('#reasoning .belief-card')].find(node=>node.textContent.includes(argumentId));if(detail){detail.open=true;detail.scrollIntoView({block:'center'})}},0)}
function initRiskMonitoring(){const switcher=document.createElement('nav');switcher.id='workspaceSwitch';switcher.className='workspace-switch';switcher.innerHTML='<button class="active" data-workspace="agent">Xã hội tác tử</button><button data-workspace="risk">Giám sát rủi ro</button>';const brand=document.querySelector('.brand');brand.insertBefore(switcher,brand.querySelector('.loop'));const workspace=document.createElement('section');workspace.id='riskWorkspace';workspace.className='risk-workspace';workspace.hidden=true;workspace.innerHTML='<aside class="risk-side"><div class="kicker">AGORA BLUE SKY</div><h1>AGORA</h1><div class="risk-side-subtitle">V3 · Giám sát rủi ro lập luận</div><p class="risk-side-copy">Theo dõi xung đột, mức định hướng và độ ưu tiên rà soát theo từng cửa sổ thời gian.</p><nav class="risk-side-switch"><button data-workspace="agent">← Xã hội tác tử</button><button class="active" data-workspace="risk">Giám sát rủi ro</button></nav></aside><section class="risk-content"><header class="risk-header" id="riskHeader"></header><section class="risk-summary" id="riskSummary"></section><main class="risk-main"><section class="risk-table-card"><div class="risk-table-title"><h2>Các lập luận cần ưu tiên rà soát</h2><small>Rank_H(B) · RS giảm dần · phá hòa bằng mã lập luận</small><div class="proxy-note">Điểm thấp có thể phản ánh dữ liệu quan hệ và phản hồi còn thưa; không đồng nghĩa lập luận an toàn, đúng hoặc không cần xem xét.</div></div><table class="risk-table"><colgroup><col style="width:5%"><col style="width:9%"><col style="width:34%"><col style="width:5%"><col style="width:5%"><col style="width:5%"><col style="width:11%"><col style="width:9%"><col style="width:8%"><col style="width:9%"></colgroup><thead><tr><th>Ưu tiên</th><th>Lập luận</th><th>Kết luận</th><th>C</th><th>S</th><th>RS</th><th>Mức</th><th>Chất lượng</th><th>Xu hướng</th><th>Xem</th></tr></thead><tbody id="riskTableBody"></tbody></table></section><aside class="risk-detail" id="riskDetail"></aside></main></section>';document.body.appendChild(workspace);document.querySelectorAll('[data-workspace]').forEach(button=>button.onclick=()=>setWorkspace(button.dataset.workspace));if(params.get('view')==='risk')setWorkspace('risk')}
'''


def _template() -> str:
    html = V2_HTML
    html = _replace(html, "<title>AGORA V2 — Autonomous Argumentative Agents</title>", "<title>AGORA V3 — Xã hội tác tử động</title>")
    html = _replace(html, "content:'V2'", "content:'V3'")
    html = _replace(html, '<div class="subtitle">V2 · Argumentative Agents</div>', '<div class="subtitle">V3 · Xã hội tác tử động</div>')
    html = _replace(html, '<div class="version">DETERMINISTIC BASELINE</div>', '<div class="version">NGỮ NGHĨA · ĐỘNG LỰC XÃ HỘI</div>')
    html = _replace(html, "</style>", V3_CSS + "\n</style>")
    html = _replace(
        html,
        '<aside class="rail"><nav class="tabs"><button class="active" data-tab="reasoning">Lập luận</button><button data-tab="activity">Hoạt động</button><button data-tab="metrics">Chỉ số</button></nav><section class="panel" id="reasoning"></section><section class="panel" id="activity" hidden></section><section class="panel" id="metrics" hidden></section></aside>',
        '<aside class="rail"><nav class="tabs"><button class="active" data-tab="reasoning">Lập luận</button><button data-tab="activity">Hoạt động</button><button data-tab="society">Xã hội</button><button data-tab="events">Sự kiện</button><button data-tab="metrics">Chỉ số</button></nav><section class="panel" id="reasoning"></section><section class="panel" id="activity" hidden></section><section class="panel" id="society" hidden></section><section class="panel" id="events" hidden></section><section class="panel" id="metrics" hidden></section></aside>',
    )
    html = _replace(html, "function metricsPanel(){", V3_JS + "\nfunction metricsPanel(){")
    html = _replace(
        html,
        "function renderPanels(){if(state.edge!==null)interactionPanel();else reasoningPanel();activityPanel();metricsPanel()}function render(){buttons();phase();renderGraph();renderPanels()}",
        "function renderPanels(){if(state.edge!==null)interactionPanel();else reasoningPanel();enhanceReasoningPanel();activityPanel();societyPanel();eventsPanel();metricsPanel()}function render(){buttons();phase();renderGraph();decorateV3Graph();renderPanels()}",
    )
    html = _replace(
        html,
        "['reasoning','activity','metrics'].forEach(id=>$(id).hidden=id!==b.dataset.tab)",
        "['reasoning','activity','society','events','metrics'].forEach(id=>$(id).hidden=id!==b.dataset.tab)",
    )
    html = _replace(
        html,
        "initLayoutControls();initNodeDragging();render();",
        "initLayoutControls();initNodeDragging();initRiskMonitoring();render();",
    )
    return html


HTML = _template()


def render_v3_html(trace: dict[str, Any], mapping: dict[str, Any], output_path: Path) -> Path:
    html = HTML.replace("__TRACE__", _json(trace)).replace("__MAPPING__", _json(mapping))
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(html, encoding="utf-8")
    return output_path
